const puzzles = [];
function add(id, category, source, instructions, lowLabel, highLabel, rows, unit = '', note = '') {
  const sources = (Array.isArray(source) ? source : [source]).map(key => ({ title: references[key][0], url: references[key][1] }));
  puzzles.push({ id, title: id, difficulty: 'medium', category, instructions, lowLabel, highLabel, note, sources,
    items: rows.map(([label, value, display]) => ({ label, value,
      valueLabel: display || `${value.toLocaleString('en-US', { maximumSignificantDigits: 6 })}${unit ? ` ${unit}` : ''}` })) });
}
function sequence(id, category, source, subject, labels, note = '') {
  add(id, category, source, `Put ${subject} first at the bottom and last at the top.`, 'First', 'Last',
    labels.map((label, index) => [label, index + 1, `Step ${index + 1} of these six`]), '', note);
}
function releases(id, category, source, subject, rows, note = '') {
  add(id, category, source, `Put the ${subject} released earliest at the bottom and the newest at the top.`, 'Earliest release', 'Latest release', rows, '', note);
}
function milestones(id, category, source, rows, note = '') {
  add(id, category, source, 'Put the milestone that happened earliest at the bottom and the most recent at the top.', 'Earliest milestone', 'Latest milestone', rows, '', note);
}

